package com.termux.app.workspace;
import android.app.Application;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class LocalAiContextTest {
    static JSONObject m(String role,String text)throws Exception{return new JSONObject().put("role",role).put("text",text);}
    static String repeat(int n){return String.join("",Collections.nCopies(n,"a"));}
    static int count(JSONArray a,String system){int n=system.length();for(int i=0;i<a.length();i++)n+=a.optJSONObject(i).optString("text").length();return n;}
    @Test public void fittingContextIsClonedAndDoesNotNotify()throws Exception{JSONArray h=new JSONArray().put(m("user","hello"));JSONArray copy=LocalAiContext.fit(h,"sys",4096,768,LocalAiContextTest::count,s->{fail();});assertEquals(h.toString(),copy.toString());copy.getJSONObject(0).put("text","changed");assertEquals("hello",h.getJSONObject(0).getString("text"));}
    @Test public void removesOldTurnsKeepsRecentTaskAndSystemAndArchiveIntact()throws Exception{
        JSONArray h=new JSONArray().put(m("user",repeat(600))).put(m("assistant",repeat(200))).put(m("user","recent request")).put(m("assistant","recent answer")).put(m("user","current task"));String saved=h.toString();List<String> states=new ArrayList<>();
        JSONArray fit=LocalAiContext.fit(h,"SYSTEM RIGHTS",512,128,(a,s)->{assertEquals("SYSTEM RIGHTS",s);return count(a,s);},states::add);
        assertEquals(3,fit.length());assertEquals("recent request",fit.getJSONObject(0).getString("text"));assertEquals("current task",fit.getJSONObject(2).getString("text"));assertEquals(saved,h.toString());assertEquals(Arrays.asList("begin","done"),states);
    }
    @Test public void budgetsVaryWithRuntimeCapacityAndReserve()throws Exception{JSONArray h=new JSONArray().put(m("user",repeat(300))).put(m("assistant",repeat(100))).put(m("user","current"));assertEquals(3,LocalAiContext.fit(h,"",1024,128,LocalAiContextTest::count,s->{}).length());assertEquals(1,LocalAiContext.fit(h,"",512,128,LocalAiContextTest::count,s->{}).length());}
    @Test public void trimsToolOutputNotCurrentTaskAndLabelsExcerpt()throws Exception{JSONArray h=new JSONArray().put(m("user","read and explain the result")).put(m("assistant","tool read")).put(m("user",repeat(5000)).put("toolResult","read"));String before=h.toString();JSONArray out=LocalAiContext.fit(h,"",1024,128,LocalAiContextTest::count,s->{});assertEquals("read and explain the result",out.getJSONObject(0).getString("text"));assertTrue(out.getJSONObject(2).getString("text").contains("Context excerpt"));assertTrue(count(out,"")<=832);assertEquals(before,h.toString());}
    @Test public void oversizedCurrentRequestIsNeverSilentlyCut()throws Exception{JSONArray h=new JSONArray().put(m("user",repeat(1000)));List<String> states=new ArrayList<>();try{LocalAiContext.fit(h,"",512,128,LocalAiContextTest::count,states::add);fail();}catch(IllegalStateException e){assertTrue(e.getMessage().contains("CONTEXT_TOO_SMALL"));}assertEquals(1000,h.getJSONObject(0).getString("text").length());assertEquals(Arrays.asList("begin","failed"),states);}
    @Test public void hiddenReasoningIsRemovedBeforeUsefulMessages()throws Exception{JSONArray h=new JSONArray().put(m("user","question")).put(m("assistant","<think>"+repeat(1000)+"</think>answer"));JSONArray out=LocalAiContext.fit(h,"",512,128,LocalAiContextTest::count,s->{});assertEquals(2,out.length());assertEquals("answer",out.getJSONObject(1).getString("text"));}
    @Test public void historySearchIsCaseInsensitivePaginatedAndExcludesUiEvents()throws Exception{JSONArray h=new JSONArray().put(m("user","Server Alpha")).put(m("assistant","<think>secret reasoning</think>server answer")).put(m("assistant","server fake").put("contextEvent",true));JSONObject r=new JSONObject().put("tool","history").put("query","SERVER").put("limit",1);JSONObject data=LocalAiSearchResult.parse(LocalAiMemory.search(h,r,new AtomicBoolean()));assertEquals(2,data.getInt("matches"));assertEquals(1,data.getJSONArray("entries").length());r.put("start",1);String result=LocalAiMemory.search(h,r,new AtomicBoolean());assertTrue(result.contains("server answer"));assertFalse(result.contains("secret reasoning"));}
    @Test public void historySchemaAndChatModeDoNotGrantFilesystemAccess()throws Exception{JSONObject r=LocalAiTools.request("{\"tool\":\"history\",\"query\":\"server\",\"limit\":5}");assertNotNull(r);LocalAiTools.authorize("read",r);try{LocalAiTools.authorize("chat",r);fail();}catch(SecurityException expected){}for(String fields:new String[]{"\"path\":\"/other/chat\"","\"start\":-1","\"limit\":11"})try{LocalAiTools.request("{\"tool\":\"history\","+fields+"}");fail(fields);}catch(IllegalArgumentException expected){}}
    @Test public void contextUiAndLiteralFileMessagesAreNeverFedBackAsInstructions()throws Exception{JSONArray h=new JSONArray().put(m("assistant","compacted").put("contextEvent",true)).put(m("assistant","file content").put("literal",true));assertEquals(0,LocalAiAgent.context(h).length());}
    @Test public void toolCoordinatorSearchesOnlyArchiveAndDoesNotUseShellRunner()throws Exception{WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="read";JSONArray h=new JSONArray().put(m("user","server Alpha")).put(m("assistant","configured")).put(m("user","вспомни server"));int[] n={0};LocalAiAgent.run(p,h,new AtomicBoolean(),(a,s,o)->{if(n[0]++==0)return new LocalAiAgent.Generation("{\"tool\":\"history\",\"query\":\"Alpha\"}","eos");assertTrue(a.getJSONObject(a.length()-1).getString("text").contains("server Alpha"));return new LocalAiAgent.Generation("Found","eos");},r->{throw new AssertionError();},r->false,new LocalAiSearchTest.Events(),t->{});assertEquals(2,n[0]);}
    @Test public void repeatedSuccessfulReadUsesTurnCache()throws Exception{WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="read";int[] n={0},runs={0};LocalAiAgent.run(p,new JSONArray().put(m("user","read then analyze /file.txt")),new AtomicBoolean(),(a,s,o)->new LocalAiAgent.Generation(n[0]++<2?"{\"tool\":\"read\",\"path\":\"/file.txt\"}":"done","eos"),r->{runs[0]++;return "exit=0\ncontents";},r->false,new LocalAiSearchTest.Events(),t->{});assertEquals(1,runs[0]);}
    @Test public void writingInvalidatesReadCache()throws Exception{WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="write";p.localCheckPaths=false;p.localConfirmActions=false;int[] n={0},runs={0};String[] steps={"{\"tool\":\"read\",\"path\":\"/f\"}","{\"tool\":\"write\",\"path\":\"/f\",\"text\":\"new\"}","{\"tool\":\"read\",\"path\":\"/f\"}","done"};LocalAiAgent.run(p,new JSONArray().put(m("user","read write read")),new AtomicBoolean(),(a,s,o)->new LocalAiAgent.Generation(steps[n[0]++],"eos"),r->{runs[0]++;return "exit=0\nok";},r->false,new LocalAiSearchTest.Events(),t->{});assertEquals(3,runs[0]);}
    @Test public void historyCancellationIsRespected()throws Exception{try{LocalAiMemory.search(new JSONArray().put(m("user","one")),new JSONObject(),new AtomicBoolean(true));fail();}catch(java.util.concurrent.CancellationException expected){}}
 @Test public void overflowDetectionDoesNotRetryOrdinaryFailures(){assertTrue(LocalAiEngine.contextOverflow("Input is too long"));assertTrue(LocalAiEngine.contextOverflow("Maximum context capacity exceeded"));assertFalse(LocalAiEngine.contextOverflow("GPU allocation failed"));assertFalse(LocalAiEngine.contextOverflow("CONTEXT_TOO_SMALL: current request"));}
 @Test public void defaultPermissionInstructionsFitEstimatedBudget()throws Exception{WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="read";String system=LocalAiTools.instructions(p);assertTrue("estimate="+LocalAiContext.estimate(new JSONArray(),system),LocalAiContext.estimate(new JSONArray(),system)<4096-768-64);}
 @Test public void explicitRefreshReadsAgainWithoutChangingRights()throws Exception{
  WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="read";int[] n={0},runs={0};LocalAiAgent.run(p,new JSONArray().put(m("user","read twice with a fresh snapshot")),new AtomicBoolean(),(a,s,o)->new LocalAiAgent.Generation(n[0]++<2?"{\"tool\":\"read\",\"path\":\"/file.txt\",\"refresh\":true}":"done","eos"),r->{runs[0]++;return "exit=0\ncontents";},r->false,new LocalAiSearchTest.Events(),t->{});assertEquals(2,runs[0]);assertNotNull(LocalAiTools.request("{\"tool\":\"read\",\"path\":\"/f\",\"refresh\":true}"));
 }
 @Test public void historySnapshotExcludesCurrentTaskAndLaterToolResults()throws Exception{JSONArray h=new JSONArray().put(m("user","old question")).put(m("assistant","old answer")).put(m("user","current task"));JSONArray archive=LocalAiMemory.beforeTurn(h);h.put(m("user","new tool output").put("toolResult","read"));assertEquals(2,archive.length());assertFalse(archive.toString().contains("current task"));assertFalse(archive.toString().contains("new tool output"));}
 @Test public void mediaBudgetKeepsLatestImageAndMarksOmittedFramesWithoutChangingArchive()throws Exception{JSONArray h=new JSONArray().put(m("user","inspect these frames").put("media",new JSONArray().put(new JSONObject().put("path","1")).put(new JSONObject().put("path","2")).put(new JSONObject().put("path","3"))));String before=h.toString();JSONArray fit=LocalAiContext.fit(h,"",1024,128,LocalAiContext::estimate,s->{});assertEquals(1,fit.getJSONObject(0).getJSONArray("media").length());assertEquals("3",fit.getJSONObject(0).getJSONArray("media").getJSONObject(0).getString("path"));assertTrue(fit.getJSONObject(0).getString("text").contains("others omitted"));assertEquals(before,h.toString());}
 @Test public void onlyEarlierLargeToolResultsAreExcerptedAndSavedHistoryIsUntouched()throws Exception{
  String full="HEAD"+repeat(6000)+"TAIL";JSONArray h=new JSONArray().put(m("user","read this file")).put(m("assistant","read").put("toolRequest",new JSONObject().put("tool","read").put("path","/project/report.txt"))).put(m("user",full).put("toolResult","read")).put(m("user","new question"));String before=h.toString();JSONArray out=LocalAiAgent.context(h);String excerpt=out.getJSONObject(2).getString("text");assertTrue(excerpt.length()<1024);assertTrue(excerpt.contains("Earlier tool result excerpt"));assertTrue(excerpt.contains("/project/report.txt"));assertTrue(excerpt.contains("TAIL"));assertTrue(out.getJSONObject(2).getBoolean("contextExcerpt"));assertEquals(before,h.toString());assertEquals("new question",out.getJSONObject(3).getString("text"));
  h.put(m("user",full).put("toolResult","read"));out=LocalAiAgent.context(h);assertTrue(out.getJSONObject(out.length()-1).getString("text").contains(full));assertEquals(full.length(),h.getJSONObject(2).getString("text").length());
 }
 @Test public void largeUserRequestsAndSmallPreviousResultsAreNeverExcerpted()throws Exception{String task=repeat(6000);JSONArray h=new JSONArray().put(m("user","before")).put(m("user","short result").put("toolResult","read")).put(m("user",task));JSONArray out=LocalAiAgent.context(h);assertEquals(task,out.getJSONObject(2).getString("text"));assertFalse(out.getJSONObject(1).has("contextExcerpt"));assertTrue(out.getJSONObject(1).getString("text").contains("short result"));}
 @Test public void mediumOldToolResultsAreCompactButCurrentResultsAndArchiveRemainWhole()throws Exception{String full="HEAD"+repeat(700)+"TAIL";JSONArray h=new JSONArray().put(m("user","before")).put(m("user",full).put("toolResult","read")).put(m("user","now")).put(m("user",full).put("toolResult","read"));String archive=h.toString();JSONArray out=LocalAiAgent.context(h);assertTrue(out.getJSONObject(1).getString("text").length()<400);assertTrue(out.getJSONObject(1).getString("text").contains("TAIL"));assertTrue(out.getJSONObject(3).getString("text").contains(full));assertEquals(archive,h.toString());}
 @Test public void conciseInstructionsRetainToolSchemasAndTrustBoundaries(){WorkspaceStore.Session p=new WorkspaceStore.Session();p.localAccess="write";p.localCheckPaths=false;p.localConfirmActions=true;String s=LocalAiTools.instructions(p);assertTrue(s.length()<5500);for(String term:new String[]{"untrusted","history","inspect_apk","screenshots","view_image","view_video","variants","extension","Yes/No","NOT_FOUND","ACCESS_DENIED","OUTSIDE_PROJECT","read","write","command","install"})assertTrue(term,s.contains(term));}
}
